\begin{equation}\label{PbDefPsiBis}
\int_\Om\nabla\psi\cdot\nabla\psi'\,d\bfx=\int_\Om\E_{p}\cdot\nabla\psi'\,d\bfx,\qquad \forall\psi'\in\mH^1_0(\Om),
\end{equation}

