There holds
\begin{equation}\label{EstimAbove}
\dsp\int_{\Om}|\curlvec \tilde{\E}_p|^2\,d\bfx=3\lambda_\bullet\int_\GL\varphi^2\,dxdy-6\int_0^1\varphi(1,y)^2\,dy.
\end{equation}
\end{lemma}

