\[
\begin{array}{rcl}
\dsp\int_{\Pi_x}|\curlvec \E_p|^2\,d\bfx&=&\dsp\int_{\Pi_x}(\partial_xE_y)^2+(\partial_zE_y)^2+(\partial_xE_z)^2+(\partial_yE_z)^2-2\partial_yE_z\partial_zE_y\,d\bfx.
\end{array}
\]
