\[
\dsp\int_{\Pi_y}|\curlvec \E_p|^2\,d\bfx=\dsp\int_{\Pi_z}|\curlvec \E_p|^2\,d\bfx=2\int_{\GL_+}|
\nabla\varphi|^2\,dxdy.
\]
