\ba
\mathcal{G}(\bs{\rho}) = \sum_{\bs{h}} a_{\bs{h}} \bs{\rho}^{\bs{h}} = \sum_{\bs{h}} a_{\bar{\bs{h}}} \bs{\rho}^{\bs{h}},
\label{monomialdecomposition}
\ea
