\ba
\label{stcrossing}
\mathcal{G}(\bs{\rho}) = \left|\frac{4 \bs{\rho}}{(1-\bs{\rho})^2}\right|^{2\De}\mathcal{G}(\hat{\bs{\rho}}),
\ea
