\begin{enumerate}\itemsep=0pt
\item[$1)$] $(x^{-}_{\theta}\otimes 1)^{2k+1}\big(x^{-}_{\theta}\otimes t^{2k+1-i}\big)w_{(k+1)\theta}=0,
