\ifdefined\hypertarget\hypertarget{sourcepointer-1}{}\fi
\noindent\textit{Source reference.} Original definition 03JL: sources/stacks-decent-spaces/pinned-original-source.tex, source lines 277--277. Navigation pointer only: the counted proof cites this statement by \textbackslash{}ref as a standing input; the deduction the counted proof has to make is carried out inside the counted span, and no part of that deduction is delegated to this pointer.\par\medskip
\ifdefined\hypertarget\hypertarget{sourcepointer-2}{}\fi
\noindent\textit{Source reference.} Original reference 03JB: focused-seeds/geometry/S9-decent-universally-bounded-permanence/ref-tags.txt, source lines 5--5. Navigation pointer only: the counted proof cites this statement by \textbackslash{}ref as a standing input; the deduction the counted proof has to make is carried out inside the counted span, and no part of that deduction is delegated to this pointer.\par\medskip
\begin{lemma}
\label{lemma-universally-bounded-permanence}
Let $S$ be a scheme. Let $X$ be an algebraic space over $S$.
Consider a commutative diagram
$$
\xymatrix{
U \ar[rd]_g \ar[rr]_f & & V \ar[ld]^h \\
& X &
}
$$
where $U$ and $V$ are schemes. If $g$ has universally bounded fibres,
and $f$ is surjective and flat, then also $h$ has universally bounded fibres.
\end{lemma}

\begin{proof}
Assume $g$ has universally bounded fibres, and $f$ is surjective and flat.
Say $n \geq 0$ is an integer which bounds the degrees of the schemes
$\Spec(k) \times_X U$ as in
Definition \ref{definition-universally-bounded}.
We claim $n$ also works for $h$.
Let $\Spec(k) \to X$ be a morphism from the spectrum of a
field to $X$. Consider the morphism of schemes
$$
\Spec(k) \times_X V \longrightarrow \Spec(k) \times_X U
$$
It is flat and surjective. By assumption the scheme
on the left is finite of degree $\leq n$ over $\Spec(k)$.
It follows from
Morphisms, Lemma \ref{morphisms-lemma-universally-bounded-permanence}
that the degree of the scheme on the right is also bounded by $n$
as desired.
\end{proof}

\end{document}

