\title{A well-order satisfies the transfinite induction schema}
\author{The Open Logic Project contributors}
\date{openlogic:set-theory/ordinals:local-snapshot-20261013; CC BY 4.0}
\begin{document}
\maketitle
\noindent\textit{Editorial note.} All delivered mathematical text is the author's own, copied from the pinned Open Logic Project unit file sources/olp-set-theory-ordinals/pinned-original-source.tex; no statement or proof step was rewritten, reordered or removed.\par\medskip
\noindent\textit{Editorial note.} The counted proof is the author's complete argument: the counted span contains no external reference (no olref inside lines 1265-1284); the existence of a <-minimal element of X is invoked from the well-ordering property, packaged in the same unit by the preceding proposition wo:strictorder (source lines 1250-1263); the author footnote after the proof (formulae may carry parameters) is commentary outside the counted proof.\par\medskip
\noindent\textit{Editorial note.} The label propwoinduction names the counted statement, and the proof environment immediately following it in the source is delivered verbatim as its proof.\par\medskip
\noindent\textit{Editorial note.} The counted statement is carried by the author's own prop environment in the unit source.\par\medskip
\noindent\textit{Allowed standard prerequisites (editorial).}\begin{itemize}
\item Well-ordering minimal-element property. Same unit, the definition of a well-order together with the preceding proposition wo:strictorder (source lines 1250-1263). The proof opens the contrapositive by collecting the counterexamples into a non-empty set X and invoking that X has a <-minimal element; this is exactly the well-ordering property packaged by wo:strictorder (every non-empty subset has a least member).
\end{itemize}\medskip
\begin{prop}\ollabel{propwoinduction}
If $<$ well-orders $A$, then for any formula $\phi(x)$:
\[
	\text{if }(\forall a \in A)((\forall b < a)\phi(b) \lif 
		\phi(a))\text{, then }(\forall a \in A)\phi(a).
\]
\end{prop}

\begin{proof}
We will prove the contrapositive. Suppose $\lnot(\forall a \in
A)\phi(a)$, i.e., that $X = \Setabs{x \in A}{\lnot\phi(x)} \neq
\emptyset$. Then $X$ has an $<$-minimal \olup{element}, $a$. So $(\forall
b < a)\phi(b)$ but $\lnot \phi(a)$. \end{proof}\noindent This last

